python - <<'PY'
import sys,json,math,numpy as np
from PIL import Image
from scipy.ndimage import gaussian_filter
sys.path.insert(0,'/app/output');import gen
p=json.load(open('/app/output/strokes.json'));im=np.asarray(Image.open('/app/target.png')).astype(np.float32)/255;H,W=im.shape[:2];mm=gen.MM_PER_PX;PL=gen.rgb_to_lab(gen.PALETTE_RGB/255);PR=gen.PALETTE_RGB/255; tb=np.stack([gaussian_filter(im[:,:,k],4.5) for k in range(3)],-1);TLb=gen.rgb_to_lab(tb);order=[8,9,14,7,2,3,1,4,5,6,11,12,10,13,15,16]; margin=int(np.ceil(8/mm));sl=(slice(margin,-margin),slice(margin,-margin));
for width in [7,8,9]:
 masks=[]
 for s in p['strokes']:
  y,x,_=gen.mask_for_segment(np.array(s['start_px']),np.array(s['end_px']),width/2,W,H); masks.append((y,x))
 for strategy in ['center','mean','centerline','medoid']:
  paints=[]
  for s,(y,x) in zip(p['strokes'],masks):
   if strategy=='center':
    c,r=map(lambda z:int(round(z)),s['center_px']); vec=TLb[r,c]
    paint=int(np.argmin(np.linalg.norm(PL-vec,axis=1)))
   elif strategy=='mean':
    vec=TLb[y,x].mean(axis=0);paint=int(np.argmin(np.linalg.norm(PL-vec,axis=1)))
   elif strategy=='medoid':
    v=TLb[y,x];paint=int(np.argmin(np.linalg.norm(v[:,None,:]-PL[None,:,:],axis=2).mean(axis=0)))
   else:
    # filter mask samples to within central 2mm of segment
    v=np.array(s['end_px'])-np.array(s['start_px']);p0=np.array(s['start_px']);d=np.clip(((x-p0[0])*v[0]+(y-p0[1])*v[1])/(v@v+1e-9),0,1);d2=(x-(p0[0]+d*v[0]))**2+(y-(p0[1]+d*v[1]))**2;keep=d2<=(2.5/mm)**2;vec=TLb[y[keep],x[keep]].mean(axis=0);paint=int(np.argmin(np.linalg.norm(PL-vec,axis=1)))
   paints.append(paint)
  # three overlay models
  cov=np.zeros((H,W),bool); last=np.ones_like(im)*np.array([224,221,213])/255; sumrgb=np.zeros_like(im);n=np.zeros((H,W),np.float32)
  # actual plan group order for each paint index
  for pp in order:
   for i,((y,x),paint) in enumerate(zip(masks,paints)):
    if paint+1 != pp:continue
    last[y,x]=PR[paint];sumrgb[y,x]+=PR[paint];n[y,x]+=1;cov[y,x]=1
  blends=np.where(n[...,None]>0,sumrgb/np.maximum(n[...,None],1),last)
  for mode,arr in [('last',last),('avg',blends)]:
   pb=np.stack([gaussian_filter(arr[:,:,k],4.5) for k in range(3)],-1);d=np.linalg.norm(gen.rgb_to_lab(pb[sl])-TLb[sl],axis=2);print(width,strategy,mode,round(float(cov[sl].mean()),4),round(float(d.mean()),2),round(float(np.percentile(d,90)),1),end='; ')
  print()
